1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  staff: 800,
63	  potion: 400,
64	  rune: 250,
65	  moonstone: 250,
66	};
67	
68	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
69	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
70	
71	const COMPONENT_BLOCK_SIZE = 3;
72	const COMPONENT_BLOCK_PREMIUM = 60;
73	
74	const countsByType = (items: Item[]): Map<string, number> =>
75	  items.reduce(
76	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
77	    new Map<string, number>(),
78	  );
79	
80	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
81	
82	/** Exactly three alike components form a building block, priced at a flat rate. */
83	const basePremiumForAlikeItems = (type: string, count: number): number =>
84	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
85	    ? COMPONENT_BLOCK_PREMIUM
86	    : count * BASE_PREMIUMS[type];
87	
88	const policyBasePremium = (items: Item[]): number =>
89	  [...countsByType(items)].reduce(
90	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
91	    0,
92	  );
93	
94	/**
95	 * Applies a rate to the amount it is measured against. Rates never compound:
96	 * premium modifiers all measure against the same base premium and are summed,
97	 * and a reimbursement rate measures against the damage amount.
98	 */
99	const amountOf = (rate: number, measuredAgainst: number): number => rate * measuredAgainst;
100	
101	/** Item-specific surcharge rates stack additively on the item's own base premium. */
102	const surchargeRateFor = (item: Item): number =>
103	  (item.cursed ? CURSE_SURCHARGE : 0) +
104	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0);
105	
106	/** Item-specific surcharges are rates on the affected item's own base premium. */
107	const itemSurchargeAmount = (items: Item[]): number =>
108	  items.reduce(
109	    (total, item) => total + amountOf(surchargeRateFor(item), BASE_PREMIUMS[item.type]),
110	    0,
111	  );
112	
113	/**
114	 * The facts a policy-wide rate is measured against. Rates key on different
115	 * things — loyalty on the customer's history, the assessment/follow-up rate on
116	 * where the quote falls in the scenario — so they travel together as context.
117	 */
118	interface PolicyContext {
119	  customer: Customer;
120	  /** Zero-based position of this quote among the scenario's quotes. */
121	  quoteOrdinal: number;
122	}
123	
124	/** Policy-wide rates apply to the policy base premium; discounts are negative. */
125	const policyRateFor = ({ customer, quoteOrdinal }: PolicyContext): number =>
126	  INITIAL_ASSESSMENT_SURCHARGE +
127	  (customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0) +
128	  (quoteOrdinal > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0);
129	
130	/** The MHPCO insures only what is on its price list. */
131	const requireInsurableItems = (items: Item[]): void => {
132	  for (const item of items) {
133	    if (!(item.type in BASE_PREMIUMS)) {
134	      throw new Error(`The MHPCO does not insure items of type ${item.type}`);
135	    }
136	  }
137	};
138	
139	const quote = (step: QuoteStep, policy: PolicyContext): StepResult => {
140	  requireInsurableItems(step.items);
141	  const base = policyBasePremium(step.items);
142	  const modifiers = itemSurchargeAmount(step.items) + amountOf(policyRateFor(policy), base);
143	  return {
144	    premium: roundPremiumInMHPCOFavour(base + modifiers + PROCESSING_FEE),
145	  };
146	};
147	
148	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
149	
150	const DEDUCTIBLE_PER_DAMAGE = 100;
151	const CAP_MULTIPLIER = 2;
152	
153	/** Payouts round down: fractions of a Gold piece stay with the MHPCO. */
154	const roundPayoutInMHPCOFavour = (amount: number): number => Math.floor(amount);
155	
156	const SEVERE_ENCHANTMENT_LEVEL = 8;
157	const SEVERE_ENCHANTMENT_REIMBURSEMENT = 0.5;
158	const FULL_REIMBURSEMENT = 1;
159	
160	/**
161	 * Damage to a heavily enchanted item is reimbursed at half its amount;
162	 * everything else — including the price list's dragon-material clause, which
163	 * grants full reimbursement — is reimbursed in full. Where both clauses apply
164	 * the half rate wins, so the enchantment level alone decides the rate.
165	 */
166	const reimbursementRateFor = (item: Item): number =>
167	  (item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_LEVEL
168	    ? SEVERE_ENCHANTMENT_REIMBURSEMENT
169	    : FULL_REIMBURSEMENT;
170	
171	const insuredCountOfType = (type: string, items: Item[]): number =>
172	  items.filter((item) => item.type === type).length;
173	
174	const claimedCountOfType = (type: string, damages: Damage[]): number =>
175	  damages.filter((damage) => damage.itemType === type).length;
176	
177	/**
178	 * A claim can run out of insured items either because the policy covers none of
179	 * that type at all, or because it covers fewer than the claim names.
180	 */
181	const overClaimMessage = (type: string, damages: Damage[], items: Item[]): string => {
182	  const insured = insuredCountOfType(type, items);
183	  if (insured === 0) return `Policy does not cover a ${type}`;
184	  return `Claim damages ${claimedCountOfType(type, damages)} ${type}s but the policy insures only ${insured} ${type}`;
185	};
186	
187	/** A damage entry together with the specific insured item it claims against. */
188	interface ClaimedDamage {
189	  damage: Damage;
190	  item: Item;
191	}
192	
193	/**
194	 * A damage entry names its item only by type, so pairing is positional within a
195	 * type: the policy may insure several items of one type, and each damage entry
196	 * claims against a distinct one. Pairing therefore happens for the damage list
197	 * as a whole — an item already claimed against is no longer available to the
198	 * next entry, which is what makes over-claiming detectable.
199	 */
200	const claimsAgainstInsuredItems = (damages: Damage[], items: Item[]): ClaimedDamage[] => {
201	  const unclaimed = [...items];
202	  return damages.map((damage) => {
203	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
204	    if (index < 0) throw new Error(overClaimMessage(damage.itemType, damages, items));
205	    return { damage, item: unclaimed.splice(index, 1)[0] };
206	  });
207	};
208	
209	/** A policy issued by a quote step, tracking how much of its cap remains. */
210	interface Policy {
211	  items: Item[];
212	  remainingCap: number;
213	}
214	
215	const insuranceSum = (items: Item[]): number =>
216	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
217	
218	const openPolicy = (items: Item[]): Policy => ({
219	  items,
220	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
221	});
222	
223	/** Every damage entry carries its own deductible, applied after any clause. */
224	const payoutForDamage = ({ damage, item }: ClaimedDamage): number =>
225	  amountOf(reimbursementRateFor(item), damage.amount) - DEDUCTIBLE_PER_DAMAGE;
226	
227	/** What the damages come to on their own, before the policy's cap limits it. */
228	const payoutBeforeCap = (damages: Damage[], items: Item[]): number =>
229	  claimsAgainstInsuredItems(damages, items).reduce(
230	    (total, claimed) => total + payoutForDamage(claimed),
231	    0,
232	  );
233	
234	/**
235	 * Settling a claim pays out and draws the policy's cap down by that amount, so
236	 * it yields both the result and the policy as it stands afterwards.
237	 */
238	/** A damage is a loss, never a gain: the MHPCO does not accept negative claims. */
239	const requireLosses = (damages: Damage[]): void => {
240	  for (const damage of damages) {
241	    if (damage.amount < 0) {
242	      throw new Error(`Damage amount ${damage.amount} is not a loss`);
243	    }
244	  }
245	};
246	
247	const settleClaim = (
248	  step: ClaimStep,
249	  policy: Policy,
250	): { result: StepResult; policy: Policy } => {
251	  requireLosses(step.incident.damages);
252	  const payout = Math.min(
253	    roundPayoutInMHPCOFavour(payoutBeforeCap(step.incident.damages, policy.items)),
254	    policy.remainingCap,
255	  );
256	  const remainingCap = policy.remainingCap - payout;
257	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
258	};
259	
260	export const runScenario = (scenario: Scenario): ScenarioResult => {
261	  /** A claim names its policy by the index of the quote step that opened it. */
262	  const policiesByQuoteStep = new Map<number, Policy>();
263	  const results = scenario.steps.map((step, index) => {
264	    if (isQuote(step)) {
265	      const context = {
266	        customer: scenario.customer,
267	        quoteOrdinal: policiesByQuoteStep.size,
268	      };
269	      policiesByQuoteStep.set(index, openPolicy(step.items));
270	      return quote(step, context);
271	    }
272	    const policy = policiesByQuoteStep.get(step.policy);
273	    if (!policy) throw new Error(`No policy created by step ${step.policy}`);
274	    const settled = settleClaim(step, policy);
275	    policiesByQuoteStep.set(step.policy, settled.policy);
276	    return settled.result;
277	  });
278	  return { results };
279	};
