3	const readStdin = async (): Promise<string> => {
4	  let input = "";
5	  process.stdin.setEncoding("utf8");
6	  for await (const chunk of process.stdin) input += chunk;
7	  return input;
8	};
9	
10	try {
11	  const scenario = JSON.parse(await readStdin()) as Scenario;
12	  process.stdout.write(JSON.stringify(runScenario(scenario)));
13	} catch (error) {
14	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
15	  process.exit(1);
16	}
